from mock_env import MockCommerceEnv
from support_agent.adapters.audit_log import InMemoryAuditLog
from support_agent.adapters.heuristic_model import HeuristicModel
from support_agent.application.audit import AuditKind
from support_agent.composition import build_service, counter_ids
from support_agent.domain.ids import ConversationId, CustomerId
from support_agent.domain.turn import SupportRequest

class FailOn(InMemoryAuditLog):
    def __init__(self, kind): super().__init__(); self.kind = kind
    def append(self, entry):
        if entry.kind is self.kind: raise OSError("audit store down")
        super().append(entry)

for kind in (AuditKind.ACTION, AuditKind.RESULT):
    env = MockCommerceEnv(); svc = build_service(env, HeuristicModel(), audit_log=FailOn(kind), new_id=counter_ids())
    try:
        for m in ["refund one wine glass from ORD-200, it broke", "yes"]:
            r = svc.handle(SupportRequest(CustomerId("CUST-001"), ConversationId("c"), m)); print(kind, ">", r.reply)
    except Exception as e: print(kind, "RAISED", repr(e))
    print("  records", len(env.records("refunds")))
EOF
